import '../models/exam_model.dart'; import '../models/question_model.dart'; import '../services/firestore_service.dart'; class ExamRepository { final FirestoreService service; ExamRepository({FirestoreService? service}):service=service??FirestoreService(); Stream<List<ExamModel>> watch(String courseId)=>service.stream('exams').map((s)=>s.docs.map((d)=>ExamModel.fromMap(d.id,d.data())).where((e)=>e.courseId==courseId).toList()); Stream<List<QuestionModel>> questions(String examId)=>service.stream('questions').map((s)=>s.docs.map((d)=>QuestionModel.fromMap(d.id,d.data())).where((q)=>q.examId==examId).toList()..sort((a,b)=>a.order.compareTo(b.order))); Future<void> saveExam(ExamModel x)=>service.setDoc('exams',x.id,x.toMap()); Future<void> saveQuestion(QuestionModel x)=>service.setDoc('questions',x.id,x.toMap()); Future<void> deleteExam(String id)=>service.deleteDoc('exams',id); }